class Solution {
public:
    int maximalNetworkRank(int n, vector<vector<int>>& roads) {
        vector<int> degree(n, 0);
        vector<unordered_set<int>> adj(n);

        for (auto& r : roads) {
            int a = r[0], b = r[1];
            degree[a]++;
            degree[b]++;
            adj[a].insert(b);
            adj[b].insert(a);
        }

        int maxDeg = 0, secondMaxDeg = 0;
        for (int i = 0; i < n; i++) {
            if (degree[i] > maxDeg) {
                secondMaxDeg = maxDeg;
                maxDeg = degree[i];
            } else if (degree[i] > secondMaxDeg) {
                secondMaxDeg = degree[i];
            }
        }

        vector<int> maxCities, secondMaxCities;
        for (int i = 0; i < n; i++) {
            if (degree[i] == maxDeg) maxCities.push_back(i);
            else if (degree[i] == secondMaxDeg) secondMaxCities.push_back(i);
        }

        int ans = 0;

        if (maxCities.size() > 1) {
            bool found = false;
            int k = maxCities.size();
            for (int i = 0; i < k && !found; i++) {
                for (int j = i + 1; j < k && !found; j++) {
                    if (!adj[maxCities[i]].count(maxCities[j])) {
                        found = true;
                    }
                }
            }
            ans = found ? 2 * maxDeg : 2 * maxDeg - 1;
        } else {
            bool found = false;
            int a = maxCities[0];
            for (int b : secondMaxCities) {
                if (!adj[a].count(b)) {
                    found = true;
                    break;
                }
            }
            ans = found ? maxDeg + secondMaxDeg : maxDeg + secondMaxDeg - 1;
        }

        return ans;
    }
};
